/// Contact cases present under `fixtures/model/contact`.
fn cases(prefix: &str) -> Vec<Fixture> {
    let dir = fixtures_root().join("model/contact");
    let mut names: Vec<String> = std::fs::read_dir(&dir)
        .map(|r| {
            r.filter_map(|e| e.ok())
                .filter(|e| e.path().join("manifest.json").exists())
                .map(|e| e.file_name().to_string_lossy().into_owned())
                .filter(|n| n.starts_with(prefix))
                .collect()
        })
        .unwrap_or_default();
    names.sort();
    names
        .into_iter()
        .map(|n| {
            let f = Fixture::open(&dir.join(&n)).unwrap();
            f.require_golden().unwrap();
            f.verify_checksums().unwrap();
            assert_no_nan(&f);
            f
        })
        .collect()
}

/// D-046 (4): a golden case containing NaN must document it; no contact
/// case does, so none may contain one.
fn assert_no_nan(f: &Fixture) {
    for q in &f.manifest().quantities {
        if let Ok(a) = f.load_f64(&q.name) {
            assert!(
                a.data.iter().all(|v| !v.is_nan()),
                "{}: {} contains NaN (undocumented, D-046)",
                f.case_id(),
                q.name
            );
        }
    }
}

fn f64s(f: &Fixture, name: &str) -> Vec<f64> {
    f.load_f64(name).unwrap().data
}

fn i64s(f: &Fixture, name: &str) -> Vec<i64> {
    f.load_i64(name).unwrap().data
}

/// Bitwise comparison (identical bit patterns; see the header for D-046).
fn assert_bits(case: &str, what: &str, got: &[f64], expected: &[f64]) {
    assert_eq!(got.len(), expected.len(), "{case}: {what}: length");
    let bad: Vec<usize> = (0..got.len())
        .filter(|&i| got[i].to_bits() != expected[i].to_bits())
        .collect();
    if let Some(&i) = bad.first() {
        panic!(
            "{case}: {what}: {} of {} entries differ; first at {i}: {:e} vs {:e} (Δ = {:e})",
            bad.len(),
            got.len(),
            got[i],
            expected[i],
            got[i] - expected[i]
        );
    }
}

fn read_input_text(f: &Fixture, role: &str) -> String {
    std::fs::read_to_string(f.input_path(role).unwrap()).unwrap()
}

/// Contact model on the case's mesh and input file, positions replayed
/// (the dimension is the number of components of `positions`).
fn model_of(f: &Fixture, compat: ContactUpstreamCompat) -> (SharedMesh, ContactMechanicsModel) {
    let dim = f.load_f64("positions").unwrap().shape[1];
    let mesh = read_mesh(&f.input_path("mesh").unwrap(), dim);
    let (shared, mut model) = contact_model(mesh, &read_input_text(f, "material"));
    model.set_upstream_compat(compat);
    let pos = f64s(f, "positions");
    model.positions_mut().as_mut_slice().copy_from_slice(&pos);
    (shared, model)
}

/// Compare a search + force assembly with the fixture.
fn check_search(f: &Fixture, model: &mut ContactMechanicsModel) {
    let c = f.case_id();
    model.search().unwrap();
    let slaves: Vec<i64> = model
        .contact_elements()
        .iter()
        .map(|e| i64::from(e.slave))
        .collect();
    let masters: Vec<i64> = model
        .contact_elements()
        .iter()
        .map(|e| i64::from(e.master.index()))
        .collect();
    assert_eq!(slaves, i64s(f, "contact_elements/slave"), "{c}: slaves");
    assert_eq!(masters, i64s(f, "contact_elements/master"), "{c}: masters");
    for (name, a) in [
        ("gaps", model.gaps().as_slice().to_vec()),
        ("normals", model.normals().as_slice().to_vec()),
        ("tangents", model.fields.tangents.as_slice().to_vec()),
        ("projections", model.fields.projections.as_slice().to_vec()),
        ("areas", model.nodal_area().as_slice().to_vec()),
    ] {
        assert_bits(c, name, &a, &f64s(f, name));
    }
    let det = model.contact_detector();
    assert_bits(
        c,
        "detector/distances",
        &[
            det.maximum_detection_distance(),
            det.minimum_detection_distance(),
            det.maximum_bounding_box(),
        ],
        &f64s(f, "detector/distances"),
    );
    model.assemble_internal_forces().unwrap();
    for (name, a) in [
        ("contact_force", &model.fields.internal_force),
        ("normal_force", &model.fields.normal_force),
        ("tangential_force", &model.fields.tangential_force),
    ] {
        assert_bits(c, name, a.borrow().as_slice(), &f64s(f, name));
    }
    let states: Vec<i64> = model
        .contact_state()
        .as_slice()
        .iter()
        .map(|&s| i64::from(akantu_contact::contact_state_code(s)))
        .collect();
    assert_eq!(states, i64s(f, "contact_state"), "{c}: contact_state");
}

/// Detection cases (flat_on_flat two-pass, test_detector meshes, rotated
/// interfaces incl. the 60° UD-363 failure mode): bitwise with the UD-363
/// and UD-002 switches.
///
/// UD-371 / UD-372: the corrected normal orientation (current
/// positions) and projection validity give the same bits as upstream's
/// rules on these configurations (rotations ≤ 60°, segment facets), so the
/// cases replay with both settings of each switch.
#[test]
fn contact_fixtures_detection() {
    for (orientation, validity) in [(false, false), (true, true), (true, false), (false, true)] {
        let compat = ContactUpstreamCompat {
            projection_metric: true,
            assembly: true,
            normal_orientation: orientation,
            projection_validity: validity,
            ..ContactUpstreamCompat::default()
        };
        for f in cases("detection_") {
            let (_shared, mut model) = model_of(&f, compat);
            check_search(&f, &mut model);
        }
    }
}

/// Corrected metric on the unrotated interfaces: identical bits (UD-363
/// changes nothing on axis-aligned facets).
#[test]
fn contact_fixtures_detection_corrected_metric_on_axis_aligned() {
    let compat = ContactUpstreamCompat {
        assembly: true,
        ..ContactUpstreamCompat::default()
    };
    for f in cases("detection_") {
        if f.case_id().contains("_rot") {
            continue;
        }
        let (_shared, mut model) = model_of(&f, compat);
        check_search(&f, &mut model);
    }
}

/// Local penalty forces and moduli (upstream expressions: UD-368 switch)
/// and the node-indexed K (UD-002 switch).
#[test]
fn contact_fixtures_moduli() {
    let corrected_rules = ContactUpstreamCompat {
        normal_orientation: false,
        projection_validity: false,
        ..ContactUpstreamCompat::all()
    };
    for (compat, f) in [ContactUpstreamCompat::all(), corrected_rules]
        .into_iter()
        .flat_map(|c| cases("moduli_").into_iter().map(move |f| (c, f)))
    {
        let c = f.case_id().to_owned();
        let (_shared, mut model) = model_of(&f, compat);
        check_search(&f, &mut model);
        let elements = model.contact_elements().to_vec();
        let (mut fl, mut kl) = (Vec::new(), Vec::new());
        for e in &elements {
            let (fnv, _) = model.local_forces(0, e).unwrap();
            fl.extend(fnv);
            let (k, _) = model.local_moduli(0, e).unwrap();
            kl.extend(k);
        }
        assert_bits(
            &c,
            "local/normal_force_linear",
            &fl,
            &f64s(&f, "local/normal_force_linear"),
        );
        assert_bits(
            &c,
            "local/normal_moduli_linear",
            &kl,
            &f64s(&f, "local/normal_moduli_linear"),
        );
        // K assembled by the model's (deformable-master, linear) resolution
        let shared = _shared;
        let mut dofs = DofManager::new("dm", akantu_comm::Communicator::serial());
        dofs.register_nodal_dofs(&shared.read().unwrap(), "displacement", 2)
            .unwrap();
        model.assemble_stiffness_matrix(&mut dofs).unwrap();
        let k = dofs.matrix("K").unwrap();
        assert_eq!(k.irn_one_based(), i64s(&f, "K/irn"), "{c}: K irn");
        assert_eq!(k.jcn_one_based(), i64s(&f, "K/jcn"), "{c}: K jcn");
        assert_bits(&c, "K/a", k.values(), &f64s(&f, "K/a"));
    }
}

/// The explicit branch of the upstream solid–contact coupler (see
/// contact_explicit.rs).
struct ExplicitContactCoupling<'a> {
    contact: &'a mut ContactMechanicsModel,
    nodes: Array<Real>,
}

impl InterceptCallback for ExplicitContactCoupling<'_> {
    fn assemble_residual(&mut self, model: &mut Delegate<'_>) -> Result<()> {
        {
            let u = model.dofs().dofs("displacement")?;
            let p = self.contact.positions_mut();
            for ((pv, x), uv) in p
                .as_mut_slice()
                .iter_mut()
                .zip(self.nodes.as_slice())
                .zip(u.as_slice())
            {
                *pv = x + uv;
            }
        }
        self.contact.search()?;
        model.assemble_residual()?;
        self.contact.assemble_internal_forces()?;
        model
            .dofs()
            .assemble_to_residual("displacement", self.contact.internal_force().view(), 1.)
    }
}

/// SHA-256 of the little-endian bit patterns, the default quiet NaN
/// canonicalised to `0x7ff8000000000000` (D-046 (3): leaves every digest of
/// a NaN-free trajectory unchanged).
fn sha_hex(a: &[f64]) -> String {
    let mut h = Sha256::new();
    for v in a {
        let bits = if v.to_bits() == 0xfff8_0000_0000_0000 {
            0x7ff8_0000_0000_0000_u64
        } else {
            v.to_bits()
        };
        h.update(bits.to_le_bytes());
    }
    h.finalize().iter().map(|b| format!("{b:02x}")).collect()
}

/// `test_explicit_dynamic` / `test_explicit_friction` trajectories: per-step
/// digests of the displacement and contact force, checkpoints and final
/// stresses, bitwise (UD-002 switch; the friction case also UD-365 and is
/// generated on the UD-001 zero-init variant).
#[test]
fn contact_fixtures_explicit() {
    for f in cases("explicit_") {
        let c = f.case_id().to_owned();
        let friction = c.ends_with("explicit_friction");
        if friction {
            // A golden of the UD-001 zero-init variant, labelled so
            let v = &f.manifest().parameters["oracle_variant"];
            assert_eq!(v["defect"].as_str(), Some("UD-001"), "{c}: variant label");
        }
        let compat = ContactUpstreamCompat {
            assembly: true,
            trial_slip_on_previous_element: true,
            ..ContactUpstreamCompat::default()
        };
        let mesh = read_mesh(&f.input_path("mesh").unwrap(), 2);
        let nodes = mesh.nodes().clone();
        let dat = read_input_text(&f, "material");
        let parser = Parser::parse_str(&dat, "material.dat").unwrap();
        let selector = PhysicalSurfaceSelector::new(&mesh, &parser).unwrap();
        let shared = SharedMesh::new(mesh);
        let mut solid = SolidMechanicsModel::with_parser(
            shared.clone(),
            None,
            "solid_mechanics_model",
            parser.clone(),
        )
        .unwrap();
        solid.set_material_selector(Box::new(ElementDataSelector::new("physical_names")));
        solid
            .init_full(&ModelOptions::new(AnalysisMethod::ExplicitLumpedMass))
            .unwrap();
        let mut contact = ContactMechanicsModel::with_parser(
            shared.clone(),
            None,
            "contact_mechanics_model",
            parser,
        )
        .unwrap();
        contact
            .init_full(AnalysisMethod::ExplicitLumpedMass)
            .unwrap();
        contact.set_surface_selector(Box::new(selector)).unwrap();
        contact.set_upstream_compat(compat);
        let x = |v: Real| FixedValue {
            value: v,
            axis: SpatialDirection::X,
        };
        let y = |v: Real| FixedValue {
            value: v,
            axis: SpatialDirection::Y,
        };
        if friction {
            solid.apply_dirichlet_bc(&x(0.0), "lower").unwrap();
            solid.apply_dirichlet_bc(&y(0.0), "lower").unwrap();
        } else {
            solid.apply_dirichlet_bc(&x(0.0), "upper").unwrap();
            solid.apply_dirichlet_bc(&x(0.0), "lower").unwrap();
        }
        let dt = f64s(&f, "time_step")[0];
        solid.set_time_step(dt, None).unwrap();
        let normal = f64s(&f, "schedule/normal");
        let shear = if friction {
            f64s(&f, "schedule/shear")
        } else {
            Vec::new()
        };
        let normal_steps = normal.len() - 1;
        let total = normal_steps + shear.len().saturating_sub(1);
        let digests = read_input_text(&f, "digests");
        let mut lines = digests.lines();
        let nb_contacts = i64s(&f, "nb_contact_elements");
        for s in 0..total {
            if friction {
                if s < normal_steps {
                    solid.apply_dirichlet_bc(&y(-normal[s]), "loading").unwrap();
                } else {
                    solid
                        .apply_dirichlet_bc(&x(shear[s - normal_steps]), "loading")
                        .unwrap();
                }
            } else {
                solid.apply_dirichlet_bc(&y(-normal[s]), "loading").unwrap();
                solid.apply_dirichlet_bc(&y(normal[s]), "fixed").unwrap();
            }
            let mut cb = ExplicitContactCoupling {
                contact: &mut contact,
                nodes: nodes.clone(),
            };
            solid.solve_step_intercepted(&mut cb, None).unwrap();
            let gaps = contact.gaps().as_slice().to_vec();
            for (g, v) in gaps.iter().zip(
                solid
                    .velocity_mut()
                    .unwrap()
                    .as_mut_slice()
                    .as_chunks_mut::<2>()
                    .0,
            ) {
                if *g > 0.0 {
                    for vi in v {
                        *vi *= 0.99;
                    }
                }
            }
            assert_eq!(
                contact.contact_elements().len() as i64,
                nb_contacts[s],
                "{c}: step {s} contacts"
            );
            // digests are recorded for every step or a stride of steps
            let step = s.to_string();
            let recorded = lines
                .clone()
                .next()
                .filter(|l| l.split(' ').next() == Some(step.as_str()));
            if let Some(line) = recorded {
                lines.next();
                let expected = format!(
                    "{s} {} {}",
                    sha_hex(solid.displacement().unwrap().as_slice()),
                    sha_hex(contact.internal_force().as_slice())
                );
                if line != expected {
                    // report the checkpoint state for diagnosis when there is one
                    let ck = format!("step_{s}/displacement");
                    if f.quantity(&ck).is_ok() {
                        assert_bits(
                            &c,
                            &ck,
                            solid.displacement().unwrap().as_slice(),
                            &f64s(&f, &ck),
                        );
                    }
                    panic!(
                        "{c}: step {s}: digest mismatch\n  got      {expected}\n  expected {line}"
                    );
                }
            }
            let ck = format!("step_{s}");
            if f.quantity(&format!("{ck}/displacement")).is_ok() {
                assert_bits(
                    &c,
                    &format!("{ck}/velocity"),
                    solid.velocity().unwrap().as_slice(),
                    &f64s(&f, &format!("{ck}/velocity")),
                );
                assert_bits(
                    &c,
                    &format!("{ck}/gaps"),
                    contact.gaps().as_slice(),
                    &f64s(&f, &format!("{ck}/gaps")),
                );
                assert_bits(
                    &c,
                    &format!("{ck}/areas"),
                    contact.nodal_area().as_slice(),
                    &f64s(&f, &format!("{ck}/areas")),
                );
                assert_bits(
                    &c,
                    &format!("{ck}/tangential_tractions"),
                    contact.tangential_tractions().as_slice(),
                    &f64s(&f, &format!("{ck}/tangential_tractions")),
                );
            }
        }
        let mat = solid.material_by_name("upper").unwrap();
        let stress = mat
            .base()
            .stress
            .get(ElementType::Quadrangle4, GhostType::NotGhost)
            .unwrap();
        assert_bits(
            &c,
            "final/stress_upper",
            stress.as_slice(),
            &f64s(&f, "final/stress_upper"),
        );
        let _ = Path::new("");
    }
}

/// UD-370: upstream cannot construct `penalty_quadratic` (its constructor
/// re-registers the penalty parameters); the port can.
#[test]
fn contact_fixtures_penalty_quadratic_construction() {
    for f in cases("penalty_quadratic_construction") {
        let msg = f.manifest().parameters["message"]
            .as_str()
            .unwrap()
            .to_owned();
        assert!(msg.contains("already registered"), "{}: {msg}", f.case_id());
        let mesh = read_mesh(&f.input_path("mesh").unwrap(), 2);
        let (_s, mut model) = contact_model(mesh, &read_input_text(&f, "material"));
        assert!(
            model
                .register_new_resolution("q", "penalty_quadratic", "")
                .is_ok()
        );
    }
}

// ---------------------------------------------------------------------------
// Adversarial cases (probe v3)
// ---------------------------------------------------------------------------

/// Local normal forces and moduli of every contact element (the model's
/// resolution has the probe-owned resolution's parameters: penalty_linear,
/// epsilon_n = 1e3).
fn check_local_normal(f: &Fixture, model: &mut ContactMechanicsModel) {
    let c = f.case_id().to_owned();
    let elements = model.contact_elements().to_vec();
    let (mut fl, mut kl) = (Vec::new(), Vec::new());
    for e in &elements {
        let (fnv, _) = model.local_forces(0, e).unwrap();
        fl.extend(fnv);
        let (k, _) = model.local_moduli(0, e).unwrap();
        kl.extend(k);
    }
    assert_bits(
        &c,
        "local/normal_force_linear",
        &fl,
        &f64s(f, "local/normal_force_linear"),
    );
    assert_bits(
        &c,
        "local/normal_moduli_linear",
        &kl,
        &f64s(f, "local/normal_moduli_linear"),
    );
}

/// Search, forces, tractions, states and local normal moduli of a single
/// recorded state; `K` when recorded.
fn check_adversarial_state(f: &Fixture, compat: ContactUpstreamCompat) {
    let c = f.case_id().to_owned();
    let (shared, mut model) = model_of(f, compat);
    check_search(f, &mut model);
    assert_bits(
        &c,
        "tangential_tractions",
        model.tangential_tractions().as_slice(),
        &f64s(f, "tangential_tractions"),
    );
    check_local_normal(f, &mut model);
    if f.quantity("K/a").is_ok() {
        let dim = model.spatial_dimension();
        let mut dofs = DofManager::new("dm", akantu_comm::Communicator::serial());
        dofs.register_nodal_dofs(&shared.read().unwrap(), "displacement", dim)
            .unwrap();
        model.assemble_stiffness_matrix(&mut dofs).unwrap();
        let k = dofs.matrix("K").unwrap();
        assert_eq!(k.irn_one_based(), i64s(f, "K/irn"), "{c}: K irn");
        assert_eq!(k.jcn_one_based(), i64s(f, "K/jcn"), "{c}: K jcn");
        assert_bits(&c, "K/a", k.values(), &f64s(f, "K/a"));
    }
}

/// Whether every accepted projection on a triangle facet lies in its
/// triangle (barycentric coordinates ≥ −extension tolerance), i.e. whether
/// upstream's box rule (UD-372) gave the same pairing as the corrected one.
fn triangle_projections_inside(f: &Fixture) -> bool {
    let proj = f64s(f, "projections");
    let slaves = i64s(f, "contact_elements/slave");
    let types = f.manifest().parameters["master_types"]
        .as_str()
        .unwrap_or("")
        .to_owned();
    if !types.contains("triangle") {
        return true;
    }
    slaves.iter().all(|&s| {
        let (a, b) = (proj[2 * s as usize], proj[2 * s as usize + 1]);
        a >= -1e-5 && b >= -1e-5 && 1.0 - a - b >= -1e-5
    })
}

/// The adversarial single-state cases (2-D slopes 44°/45°/89°/90° where the
/// UD-363 Newton metric fails, the ridge tie-break, the warped-quadrangle
/// and triangle 3-D surfaces with assembled K): bitwise with every switch
/// (upstream everywhere). The corrected orientation and validity rules
/// (UD-371, UD-372) give the same bits wherever upstream's rules are right
/// — rotations below 90°, segment and quadrangle facets, triangles whose
/// oracle projections lie in their facet — which is asserted too.
#[test]
fn contact_fixtures_adversarial() {
    let all = cases("adversarial_");
    let single: Vec<&Fixture> = all
        .iter()
        .filter(|f| {
            let c = f.case_id();
            !c.ends_with("_friction")
                && !c.ends_with("_quadratic3d")
                && !c.contains("/adversarial_tri_")
        })
        .collect();
    assert_eq!(single.len(), 9, "adversarial single-state cases");
    for f in single {
        check_adversarial_state(f, ContactUpstreamCompat::all());
        let corrected_rules = ContactUpstreamCompat {
            normal_orientation: false,
            projection_validity: false,
            ..ContactUpstreamCompat::all()
        };
        if triangle_projections_inside(f) {
            check_adversarial_state(f, corrected_rules);
        } else {
            // UD-372 seen in the oracle data: the corrected rule pairs a
            // slave whose upstream projection lies outside its triangle
            // with the facet that contains it
            let (_s, mut model) = model_of(f, corrected_rules);
            model.search().unwrap();
            let masters: Vec<i64> = model
                .contact_elements()
                .iter()
                .map(|e| i64::from(e.master.index()))
                .collect();
            println!(
                "{}: oracle projections outside their triangle (UD-372); corrected masters {masters:?} vs oracle {:?}",
                f.case_id(),
                i64s(f, "contact_elements/master")
            );
            assert_ne!(masters, i64s(f, "contact_elements/master"));
        }
    }
}

/// `adversarial_curved3d_friction` (UD-001 zero-init oracle variant): 24
/// prescribed sliding steps of the slave body across master facet
/// boundaries (search and force assembly per step: elements, gaps,
/// normals, tangents, projections, areas, forces, tractions, states), then
/// upstream's slip moduli of the slaves in slip — bitwise with every
/// switch (UD-365 previous-facet slip increment, UD-369 upstream moduli).
#[test]
fn contact_fixtures_adversarial_friction() {
    let all = cases("adversarial_curved3d_friction");
    assert_eq!(all.len(), 1, "the variant golden must be present");
    for f in all {
        let c = f.case_id().to_owned();
        let v = &f.manifest().parameters["oracle_variant"];
        assert_eq!(v["defect"].as_str(), Some("UD-001"), "{c}: variant label");
        assert_eq!(
            v["patch"].as_str(),
            Some("oracle/patches/variants/ud001-contact-zero-init.patch")
        );
        let (_shared, mut model) = model_of(&f, ContactUpstreamCompat::all());
        let mesh = read_mesh(&f.input_path("mesh").unwrap(), 3);
        let nodes = mesh.nodes().as_slice().to_vec();
        let lower = nodes_of_physical(&mesh, "lower");
        let upper = nodes_of_physical(&mesh, "upper");
        drop(mesh);
        let steps = f.manifest().parameters["steps"].as_i64().unwrap();
        for s in 0..steps {
            #[allow(clippy::cast_precision_loss)] // step counts are tiny
            let sf = s as Real;
            let (sx, sy) = (0.13 + 0.025 * sf, 0.07 + 0.0125 * sf);
            #[allow(clippy::cast_precision_loss)]
            let sz = -0.02 - 0.0015 * s.min(10) as Real;
            {
                let p = model.positions_mut().as_mut_slice();
                for &n in &lower {
                    let i = 3 * n as usize;
                    let (x, y, z) = (nodes[i], nodes[i + 1], nodes[i + 2]);
                    p[i] = x;
                    p[i + 1] = y;
                    p[i + 2] = z + (z + 1.) * (-0.15 * (x * x + y * y));
                }
                for &n in &upper {
                    let i = 3 * n as usize;
                    p[i] = nodes[i] + sx;
                    p[i + 1] = nodes[i + 1] + sy;
                    p[i + 2] = nodes[i + 2] + sz;
                }
            }
            if s == 0 {
                assert_bits(
                    &c,
                    "positions",
                    model.positions().as_slice(),
                    &f64s(&f, "positions"),
                );
            }
            model.search().unwrap();
            let pre = format!("step_{s}/");
            let slaves: Vec<i64> = model
                .contact_elements()
                .iter()
                .map(|e| i64::from(e.slave))
                .collect();
            let masters: Vec<i64> = model
                .contact_elements()
                .iter()
                .map(|e| i64::from(e.master.index()))
                .collect();
            assert_eq!(
                slaves,
                i64s(&f, &format!("{pre}contact_elements/slave")),
                "{c}: {pre}slaves"
            );
            assert_eq!(
                masters,
                i64s(&f, &format!("{pre}contact_elements/master")),
                "{c}: {pre}masters"
            );
            for (name, a) in [
                ("gaps", model.gaps().as_slice().to_vec()),
                ("normals", model.normals().as_slice().to_vec()),
                ("tangents", model.fields.tangents.as_slice().to_vec()),
                ("projections", model.fields.projections.as_slice().to_vec()),
                ("areas", model.nodal_area().as_slice().to_vec()),
            ] {
                assert_bits(
                    &c,
                    &format!("{pre}{name}"),
                    &a,
                    &f64s(&f, &format!("{pre}{name}")),
                );
            }
            model.assemble_internal_forces().unwrap();
            for (name, a) in [
                (
                    "normal_force",
                    model.fields.normal_force.borrow().as_slice().to_vec(),
                ),
                (
                    "tangential_force",
                    model.fields.tangential_force.borrow().as_slice().to_vec(),
                ),
                (
                    "tangential_tractions",
                    model.fields.tangential_tractions.as_slice().to_vec(),
                ),
            ] {
                assert_bits(
                    &c,
                    &format!("{pre}{name}"),
                    &a,
                    &f64s(&f, &format!("{pre}{name}")),
                );
            }
            let states: Vec<i64> = model
                .contact_state()
                .as_slice()
                .iter()
                .map(|&st| i64::from(akantu_contact::contact_state_code(st)))
                .collect();
            assert_eq!(
                states,
                i64s(&f, &format!("{pre}contact_state")),
                "{c}: {pre}states"
            );
        }
        let which = i64s(&f, "slip/slaves");
        assert!(!which.is_empty(), "{c}: slaves in slip");
        let elements = model.contact_elements().to_vec();
        let mut kl = Vec::new();
        for w in &which {
            let e = elements.iter().find(|e| i64::from(e.slave) == *w).unwrap();
            let (_, kt) = model.local_moduli(0, e).unwrap();
            kl.extend(kt);
        }
        assert_bits(&c, "slip/moduli", &kl, &f64s(&f, "slip/moduli"));
    }
}

/// `adversarial_quadratic3d`: quadratic master facets
/// (`quadrangle_8`) are unsupported upstream — the natural projection needs
/// `computeD2NDS2`, implemented only for `segment_2`, `triangle_3` and
/// `quadrangle_4` — and in the port, which returns `Error::NotImplemented`
/// from the search instead of upstream's exception.
#[test]
fn contact_fixtures_adversarial_quadratic_master() {
    let all = cases("adversarial_quadratic3d");
    assert_eq!(all.len(), 1, "the error-path case must be present");
    for f in all {
        let msg = f.manifest().parameters["message"]
            .as_str()
            .unwrap()
            .to_owned();
        assert!(msg.contains("computeD2NDS2"), "{}: {msg}", f.case_id());
        let mesh = read_mesh(&f.input_path("mesh").unwrap(), 3);
        let nodes = mesh.nodes().as_slice().to_vec();
        let lower = nodes_of_physical(&mesh, "lower");
        let upper = nodes_of_physical(&mesh, "upper");
        let (_s, mut model) = contact_model(mesh, &read_input_text(&f, "material"));
        {
            let p = model.positions_mut().as_mut_slice();
            for &n in &lower {
                let i = 3 * n as usize;
                let (x, y, z) = (nodes[i], nodes[i + 1], nodes[i + 2]);
                p[i + 2] = z + (z + 1.) * (-0.15 * (x * x + y * y));
            }
            for &n in &upper {
                let i = 3 * n as usize;
                p[i] = nodes[i] + 0.13;
                p[i + 1] = nodes[i + 1] + 0.07;
                p[i + 2] = nodes[i + 2] - 0.05;
            }
        }
        for compat in [
            ContactUpstreamCompat::all(),
            ContactUpstreamCompat::default(),
        ] {
            model.set_upstream_compat(compat);
            let e = model
                .search()
                .expect_err("quadratic master facets are unsupported");
            let text = e.to_string();
            println!("{}: port error: {text}", f.case_id());
            assert!(matches!(e, akantu_core::Error::NotImplemented(_)), "{text}");
            assert!(text.contains("computeD2NDS2"), "{text}");
        }
    }
}

/// `adversarial_curved3d_tri` with the corrected defaults. Upstream finds
/// no contact on this structured triangulated surface: its Newton metric
/// (UD-363, `GᵀG` instead of `GGᵀ`) diverges on triangles whose two edge
/// vectors from node 0 are not orthogonal of equal length (|ξ| ≈ 1e27 after
/// 100 iterations), which the replay reproduces bitwise. With the corrected
/// metric the port finds the penetrating slaves. With upstream's box rule
/// 6 of those 8 projections lie outside their triangle (UD-372); the
/// corrected rule keeps every contact the box rule finds and moves 4 of
/// them to the facet that contains the projection — the 2 others project
/// outside every facet around their closest master node (upstream's
/// candidate set), where the box rule remains the fallback.
#[test]
fn contact_fixtures_adversarial_triangles_corrected_defaults() {
    let all = cases("adversarial_curved3d_tri");
    assert_eq!(all.len(), 1);
    let f = &all[0];
    assert!(
        i64s(f, "contact_elements/slave").is_empty(),
        "oracle: no contact (UD-363)"
    );
    let box_rule = ContactUpstreamCompat {
        projection_validity: true,
        ..ContactUpstreamCompat::default()
    };
    let (_s, mut b) = model_of(f, box_rule);
    b.search().unwrap();
    let (_s, mut d) = model_of(f, ContactUpstreamCompat::default());
    d.search().unwrap();
    let slaves = |m: &ContactMechanicsModel| -> Vec<i32> {
        m.contact_elements().iter().map(|e| e.slave).collect()
    };
    let outside = |m: &ContactMechanicsModel| -> usize {
        m.contact_elements()
            .iter()
            .filter(|e| {
                let xi = m.fields.projections.tuple(e.slave as usize);
                xi[0] < -1e-5 || xi[1] < -1e-5 || 1.0 - xi[0] - xi[1] < -1e-5
            })
            .count()
    };
    println!(
        "{}: corrected metric + box rule: {} contacts ({} projections outside their triangle); corrected defaults: {} contacts ({} outside)",
        f.case_id(),
        b.contact_elements().len(),
        outside(&b),
        d.contact_elements().len(),
        outside(&d)
    );
    assert!(!d.contact_elements().is_empty());
    assert_eq!(
        slaves(&d),
        slaves(&b),
        "no contact lost by the UD-372 correction"
    );
    assert_eq!(
        (outside(&b), outside(&d)),
        (6, 2),
        "projections outside their triangle"
    );
}

/// The triangle cases of UD-372
/// (`adversarial_tri_{edges,valley,fallback}`, UD-001 zero-init oracle
/// variant): master triangles whose right angle is at their first node, so
/// that upstream's UD-363 metric is exact on a flat master and its Newton
/// converges — upstream then finds contacts and pairs slaves with triangles
/// that do not contain their projection (its `[−1 − tol, 1 + tol]` box
/// rule). Compat (`all()`): every recorded value bitwise. Corrected
/// default: every contact upstream finds is kept, each paired with a
/// triangle that contains its projection unless none around the closest
/// master node does (then exactly upstream's box candidate: projection and
/// facet bitwise).
#[test]
fn contact_fixtures_adversarial_triangles_ud372_oracle() {
    let all = cases("adversarial_tri_");
    assert_eq!(all.len(), 3, "the three triangle cases");
    let inside = |xi: &[Real]| {
        let t = 1e-5;
        xi[0] >= -t && xi[1] >= -t && 1.0 - xi[0] - xi[1] >= -t
    };
    for f in &all {
        let c = f.case_id().to_owned();
        let v = &f.manifest().parameters["oracle_variant"];
        assert_eq!(
            v["defect"].as_str(),
            Some("UD-001"),
            "{c}: oracle variant label"
        );
        assert_no_nan(f);
        // compat: bitwise
        let (_s, mut m) = model_of(f, ContactUpstreamCompat::all());
        check_search(f, &mut m);
        let up: Vec<(i32, i64)> = m
            .contact_elements()
            .iter()
            .map(|e| (e.slave, e.master.index() as i64))
            .collect();
        let up_proj = m.fields.projections.clone();
        let up_gaps = m.gaps().clone();
        let outside = up
            .iter()
            .filter(|(s, _)| !inside(up_proj.tuple(*s as usize)))
            .count();
        assert!(!up.is_empty(), "{c}: upstream finds contacts");
        assert!(
            outside > 0,
            "{c}: upstream pairs slaves with triangles that do not contain their projection"
        );
        // corrected default
        let (_s, mut d) = model_of(f, ContactUpstreamCompat::default());
        d.search().unwrap();
        assert_eq!(
            d.contact_elements()
                .iter()
                .map(|e| e.slave)
                .collect::<Vec<_>>(),
            up.iter().map(|e| e.0).collect::<Vec<_>>(),
            "{c}: the corrected rule keeps every contact upstream finds"
        );
        let (mut changed, mut fallback) = (0, 0);
        for e in d.contact_elements() {
            let s = e.slave as usize;
            let xi = d.fields.projections.tuple(s);
            let (_, um) = up.iter().find(|(us, _)| *us as usize == s).unwrap();
            if !inside(xi) {
                fallback += 1;
                assert_eq!(
                    e.master.index() as i64,
                    *um,
                    "{c}: fallback slave {s}: facet"
                );
                assert_eq!(
                    (xi[0].to_bits(), xi[1].to_bits()),
                    (up_proj.tuple(s)[0].to_bits(), up_proj.tuple(s)[1].to_bits()),
                    "{c}: fallback slave {s}: projection"
                );
            }
            if *um != e.master.index() as i64 {
                changed += 1;
                println!(
                    "  {c}: slave {s}: upstream facet {um} xi {:?} gap {:.5} -> facet {} xi ({:.4}, {:.4}) gap {:.5}",
                    up_proj.tuple(s),
                    up_gaps.tuple(s)[0],
                    e.master.index(),
                    xi[0],
                    xi[1],
                    d.gaps().tuple(s)[0]
                );
            }
        }
        println!(
            "{c}: compat bitwise ({} contacts, {outside} projections outside their triangle upstream); default: {changed} re-paired, {fallback} fallbacks",
            up.len()
        );
        assert!(changed > 0, "{c}: the corrected rule re-pairs");
        if c.ends_with("tri_fallback") {
            assert!(fallback > 0, "{c}: fallbacks expected");
        } else {
            assert_eq!(fallback, 0, "{c}: no fallback expected");
        }
    }
}
